// Render the harness results as specs/epics/freeploy-coolify-parity/parity/HARNESS.md
// from visual-report.json and the two capture.json files. Regenerated by the
// parity workflow on every run; the inventory README links to it.
//
//   node tools/parity/report.ts [--out tools/parity/out] [--parity specs/epics/freeploy-coolify-parity/parity]
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const opt = (k: string, d: string) => {
  const i = args.indexOf(`--${k}`);
  return i === -1 ? d : args[i + 1];
};
const out = opt("out", "tools/parity/out");
const parity = opt("parity", "specs/epics/freeploy-coolify-parity/parity");
const read = (f: string) => (existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null);
const report = read(join(parity, "visual-report.json"));
const ref = read(join(out, "reference", "capture.json"));
const tgt = read(join(out, "target", "capture.json"));
const env = existsSync(join(out, "reference.env")) ? readFileSync(join(out, "reference.env"), "utf8") : "";
const coolifyRef = env.match(/^COOLIFY_REF=(.*)$/m)?.[1] ?? "?";
const inventory = read(join(parity, "routes.web.json"));
const visualRoutes = inventory ? inventory.rows.filter((r: { visual: boolean; method: string }) => r.visual && r.method === "GET").length : 0;

const pct = (n: number, d: number) => (d ? `${((n / d) * 100).toFixed(1)}%` : "—");
const L: string[] = [];
L.push("# Parity harness results");
L.push("");
L.push(`Generated by \`tools/parity/report.ts\` in the parity workflow. Reference: Coolify at \`${coolifyRef}\`, built from source. Gate: ≤ ${(0.5).toFixed(1)}% differing pixels per screenshot (desktop 1440×900 and mobile 390×844, light and dark) **and** an exact DOM/copy match, brand words normalised.`);
L.push("");
L.push("| | Value |");
L.push("|---|---|");
L.push(`| Visual routes in the inventory | ${visualRoutes} |`);
L.push(`| Captured on the reference | ${ref ? ref.captured.length : "not run"} (${ref ? ref.skipped.length : 0} skipped: missing fixture or error) |`);
L.push(`| Captured on Freeploy | ${tgt ? `${tgt.captured.length} at ${tgt.base}` : "no target — Freeploy stage is not deployed yet"} |`);
if (report) {
  const s = report.summary;
  L.push(`| Routes matched (pass) | ${s.pass} of ${s.routes} (${pct(s.pass, s.routes)}) |`);
  L.push(`| Routes differing (fail) | ${s.fail} |`);
  L.push(`| Routes not rendered by Freeploy | ${s.missing} |`);
}
L.push("");
if (ref?.skipped?.length) {
  L.push("## Reference routes not captured");
  L.push("");
  L.push("Each needs a fixture (DP1 adds them milestone by milestone) or is an error to fix.");
  L.push("");
  for (const s of ref.skipped.slice(0, 200)) L.push(`- \`${s.id}\` — ${s.reason}`);
  L.push("");
}
if (report?.routes?.some((r: { status: string }) => r.status === "fail")) {
  L.push("## Differing routes");
  L.push("");
  L.push("| Route | Worst diff | DOM |");
  L.push("|---|---:|---|");
  for (const r of report.routes.filter((x: { status: string }) => x.status === "fail")) {
    const dom = r.shots.every((s: { dom: { equal: boolean } }) => s.dom.equal) ? "equal" : "differs";
    L.push(`| \`${r.id}\` | ${(r.worstRatio * 100).toFixed(2)}% | ${dom} |`);
  }
  L.push("");
}
writeFileSync(join(parity, "HARNESS.md"), L.join("\n"));
console.log("wrote HARNESS.md");
